import numpy as np
from PIL import Image
I=np.array(Image.open('/app/output/record_settle_clear4/last/ego.jpg').convert('RGB')); D=np.load('/app/output/record_settle_clear4/last_depth_ego.npy')
mask=(I.mean(2)<70)&(D>0)
# components 8-connected
H,W=mask.shape; seen=np.zeros_like(mask); comps=[]
for v in range(H):
 for u in range(W):
  if not mask[v,u] or seen[v,u]: continue
  st=[(v,u)]; seen[v,u]=1; pts=[]
  while st:
   y,x=st.pop(); pts.append((y,x))
   for yy in range(max(0,y-1),min(H,y+2)):
    for xx in range(max(0,x-1),min(W,x+2)):
     if mask[yy,xx] and not seen[yy,xx]: seen[yy,xx]=1; st.append((yy,xx))
  if len(pts)>40:
   a=np.array(pts); comps.append((len(pts),(a[:,1].min(),a[:,0].min(),a[:,1].max(),a[:,0].max())))
print(sorted(comps,reverse=True)[:20])
